before.css:
body { font-family: system-ui, sans-serif; margin: 0; color: #222; }

header { background: #2f855a; color: white; padding: 24px; }

main { padding: 24px; display: grid; gap: 16px; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }

.card { border: 1px solid #ddd; border-radius: 8px; padding: 12px; background: #fff; }

.badge { display: inline-block; padding: 4px 8px; border-radius: 4px; background: #2f855a; color: #fff; }

.card, .card * {
  will-change: transform, opacity;
}

before.js:
const counter = document.getElementById('counter');

let ticks = 0;

setInterval(function () { ticks++; counter.textContent = 'Ticks: ' + ticks; }, 1000);

function resizeCards() {
  const cards = document.querySelectorAll('.card');
  for (let i = 0; i < cards.length; i++) {
    const h = cards[i].offsetHeight;
    cards[i].style.minHeight = (h % 7) + 100 + 'px';
  }
}
setInterval(resizeCards, 50);

let lastWidth = 0;
function poll() {
  const w = document.body.getBoundingClientRect().width;
  if (w !== lastWidth) { lastWidth = w; }
  document.querySelectorAll('.card').forEach(function (c) { c.dataset.seen = String(Date.now()); });
  requestAnimationFrame(poll);
}
requestAnimationFrame(poll);

